source("bscode-source.R", local = TRUE)

bscode_dependency <- function() {
  htmltools::htmlDependency(
    name = "bscode",
    version = "0.0.0.9001",
    src = c(href = "bscode"),
    stylesheet = "bscode.css",
    script = "bscode.js"
  )
}

.bscode_state <- new.env(parent = emptyenv())

`%||%` <- function(x, y) {
  if (is.null(x)) y else x
}

has_class <- function(x, class) {
  if (!inherits(x, "shiny.tag")) {
    return(FALSE)
  }

  classes <- htmltools::tagGetAttribute(x, "class") %||% ""
  class %in% strsplit(classes, "\\s+")[[1L]]
}

is_bscode_nav_panel <- function(x) {
  has_class(x, "tab-pane")
}

is_bscode_nav_spacer <- function(x) {
  has_class(x, "bslib-nav-spacer")
}

panel_label <- function(x) {
  label <- htmltools::tagGetAttribute(x, "title") %||%
    htmltools::tagGetAttribute(x, "data-value") %||%
    "panel"

  as.character(label)
}

warn_missing_icons <- function(items) {
  panels <- Filter(is_bscode_nav_panel, items)
  missing <- vapply(
    panels,
    function(panel) is.null(attr(panel, "_shiny_icon")),
    logical(1)
  )

  if (!any(missing) || isTRUE(.bscode_state$missing_icon_warning)) {
    return(invisible(NULL))
  }

  labels <- vapply(panels[missing], panel_label, character(1))
  warning(
    paste0(
      "Icons are recommended for page_bscode() navigation. ",
      "Using the first letter as a fallback for: ",
      paste(labels, collapse = ", "),
      "."
    ),
    call. = FALSE
  )

  .bscode_state$missing_icon_warning <- TRUE
  invisible(NULL)
}

prepare_panel_fill <- function(item, fillable) {
  if (!is_bscode_nav_panel(item)) {
    return(item)
  }

  value <- htmltools::tagGetAttribute(item, "data-value")
  should_fill <- isTRUE(fillable) ||
    (is.character(fillable) && !is.null(value) && value %in% fillable)

  if (!should_fill) {
    return(htmltools::tagAppendAttributes(item, class = "bscode-pane-scroll"))
  }

  item <- htmltools::tagAppendAttributes(item, class = "bscode-pane-fill")
  bslib::as_fill_carrier(item)
}

make_brand <- function(title, brand) {
  if (identical(brand, FALSE)) {
    return(NULL)
  }

  label <- if (is.character(title) && length(title) == 1L) title else "bscode"

  if (is.null(brand)) {
    if (!is.character(title) || length(title) != 1L || !nzchar(trimws(title))) {
      return(NULL)
    }

    brand <- substr(trimws(title), 1L, 1L)
  }

  htmltools::div(
    class = "bscode-brand",
    title = label,
    `aria-label` = label,
    brand
  )
}

split_navset <- function(navset) {
  if (!inherits(navset, "shiny.tag")) {
    stop("Unable to build the bslib navigation container.", call. = FALSE)
  }

  children <- navset$children
  nav_index <- which(vapply(children, has_class, logical(1), class = "nav"))
  content_index <- which(vapply(children, has_class, logical(1), class = "tab-content"))

  if (length(nav_index) != 1L || length(content_index) != 1L) {
    stop(
      "Unable to locate the navigation and content elements produced by bslib::navset_pill().",
      call. = FALSE
    )
  }

  list(
    nav = children[[nav_index]],
    content = children[[content_index]]
  )
}

bscode_dependency <- function() {
  path <- system.file("www", package = "bscode")

  htmltools::htmlDependency(
    name = "bscode",
    version = as.character(utils::packageVersion("bscode")),
    src = c(file = path),
    stylesheet = "bscode.css",
    script = "bscode.js"
  )
}

#' A VS Code-inspired activity bar page
#'
#' Creates a screen-filling bslib page whose navigation is displayed as a
#' compact activity bar on the left or right. The dots must contain
#' [bslib::nav_panel()] and [bslib::nav_spacer()] objects.
#'
#' @param ... Navigation items created by [bslib::nav_panel()] or
#'   [bslib::nav_spacer()].
#' @param header Optional UI displayed above every navigation panel.
#' @param title Window title and source of the default brand letter.
#' @param id Navigation input ID, compatible with [bslib::nav_select()].
#' @param selected Value of the initially selected panel.
#' @param position Position of the activity bar: `"left"` or `"right"`.
#' @param size Activity bar size: `"sm"`, `"md"`, `"lg"`, or `"xl"`.
#' @param fillable `TRUE` to make every panel fill the viewport, `FALSE` to use
#'   normal scrolling, or a character vector containing panel values to fill.
#' @param fillable_mobile Whether the page fills the viewport on narrow screens.
#' @param tooltip_placement Tooltip placement. `"auto"` uses the side opposite
#'   the activity bar. Use `NULL` to disable tooltips.
#' @param theme A [bslib::bs_theme()] object. The default uses VS Code blue as
#'   the Bootstrap primary color.
#' @param brand Optional UI shown at the top of the activity bar. `NULL` uses
#'   the first letter of a character `title`; `FALSE` removes the brand.
#' @param lang Language attribute passed to [bslib::page_fillable()].
#'
#' @return A Shiny page UI.
#' @export
page_bscode <- function(
  ...,
  header = NULL,
  title = NULL,
  id = NULL,
  selected = NULL,
  position = c("left", "right"),
  size = c("sm", "md", "lg", "xl"),
  fillable = TRUE,
  fillable_mobile = TRUE,
  tooltip_placement = "auto",
  theme = bslib::bs_theme(primary = "#007ACC"),
  brand = NULL,
  lang = NULL
) {
  position <- match.arg(position)
  size <- match.arg(size)

  if (!is.null(tooltip_placement)) {
    tooltip_placement <- match.arg(
      tooltip_placement,
      c("auto", "top", "right", "bottom", "left")
    )
  }

  valid_fillable <-
    (is.logical(fillable) && length(fillable) == 1L && !is.na(fillable)) ||
    is.character(fillable)

  if (!valid_fillable) {
    stop("`fillable` must be TRUE, FALSE, or a character vector of panel values.", call. = FALSE)
  }

  items <- list(...)

  if (!length(items)) {
    stop("page_bscode() requires at least one nav_panel().", call. = FALSE)
  }

  valid <- vapply(
    items,
    function(item) is_bscode_nav_panel(item) || is_bscode_nav_spacer(item),
    logical(1)
  )

  if (!all(valid)) {
    item_names <- names(items) %||% rep("", length(items))
    named_invalid <- unique(item_names[!valid & nzchar(item_names)])
    unnamed_invalid <- which(!valid & !nzchar(item_names))
    details <- character()

    if (length(named_invalid)) {
      details <- c(
        details,
        paste0(
          "Unsupported argument(s): ",
          paste(sprintf("`%s`", named_invalid), collapse = ", "),
          "."
        )
      )
    }

    if (length(unnamed_invalid)) {
      details <- c(
        details,
        paste0(
          "Invalid unnamed item(s) at position(s): ",
          paste(unnamed_invalid, collapse = ", "),
          "."
        )
      )
    }

    stop(
      paste(
        c(
          details,
          "Every item in `...` must be created by bslib::nav_panel() or bslib::nav_spacer()."
        ),
        collapse = " "
      ),
      call. = FALSE
    )
  }

  warn_missing_icons(items)
  items <- lapply(items, prepare_panel_fill, fillable = fillable)

  navset <- do.call(
    bslib::navset_pill,
    c(items, list(id = id, selected = selected))
  )

  parts <- split_navset(navset)
  nav <- htmltools::tagAppendAttributes(parts$nav, class = "bscode-nav")
  content <- htmltools::tagAppendAttributes(
    parts$content,
    class = "bscode-tab-content"
  )
  content <- bslib::as_fill_carrier(content)

  navset$children <- list(
    htmltools::div(
      class = "bscode-activity-bar",
      make_brand(title, brand),
      nav
    ),
    htmltools::tags$main(
      class = "bscode-content",
      if (!is.null(header)) {
        htmltools::div(class = "bscode-header", header)
      },
      content
    )
  )

  shell <- htmltools::tagAppendAttributes(
    navset,
    class = paste(
      "bscode-shell",
      paste0("bscode-position-", position),
      paste0("bscode-size-", size)
    ),
    `data-bscode-position` = position,
    `data-bscode-tooltip-placement` = tooltip_placement %||% "none"
  )
  shell <- bslib::as_fill_carrier(shell)

  bslib::page_fillable(
    class = "bscode-page",
    bscode_dependency(),
    shell,
    padding = 0,
    gap = 0,
    fillable_mobile = fillable_mobile,
    title = title,
    theme = theme,
    lang = lang
  )
}

html,
body {
  width: 100%;
  height: 100%;
}

.bscode-page {
  height: 100vh;
  height: 100dvh;
  min-height: 0;
  margin: 0;
  overflow: hidden;
}

.bscode-page > .bscode-shell {
  flex: 1 1 auto;
  height: 100%;
  min-height: 0;
}

.bscode-shell {
  display: flex;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  background: var(--bs-body-bg);
}

.bscode-position-left {
  flex-direction: row;
}

.bscode-position-right {
  flex-direction: row-reverse;
}

.bscode-activity-bar {
  display: flex;
  flex: 0 0 58px;
  flex-direction: column;
  width: 58px;
  min-height: 0;
  background: var(--bs-primary);
  box-shadow: 1px 0 0 rgba(15, 23, 42, 0.12);
}

.bscode-position-right .bscode-activity-bar {
  box-shadow: -1px 0 0 rgba(15, 23, 42, 0.12);
}

.bscode-brand {
  display: grid;
  flex: 0 0 58px;
  place-items: center;
  width: 58px;
  height: 58px;
  color: rgba(255, 255, 255, 0.98);
  font-size: 1.2rem;
  font-weight: 500;
  letter-spacing: -0.03em;
  border-bottom: 1px solid rgba(255, 255, 255, 0.16);
  user-select: none;
}

.bscode-brand > svg,
.bscode-brand > img {
  max-width: 1.6rem;
  max-height: 1.6rem;
}

.bscode-nav {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  flex-wrap: nowrap;
  width: 100%;
  min-height: 0;
  padding: 0;
  border-radius: 0;
}

.bscode-nav > .nav-item {
  width: 100%;
}

.bscode-nav .bslib-nav-spacer {
  margin-top: auto;
}

.bscode-nav .nav-link {
  display: grid;
  place-items: center;
  width: 58px;
  height: 54px;
  padding: 0;
  border: 0;
  border-radius: 0;
  color: rgba(255, 255, 255, 0.68);
  background: transparent;
  font-size: 0;
}

.bscode-position-left .bscode-nav .nav-link {
  border-left: 3px solid transparent;
}

.bscode-position-right .bscode-nav .nav-link {
  border-right: 3px solid transparent;
}

.bscode-nav .nav-link svg {
  width: 1.35rem !important;
  height: 1.35rem !important;
  max-width: 1.35rem !important;
  max-height: 1.35rem !important;
  font-size: 1.35rem !important;
  line-height: 1;
}

.bscode-nav .nav-link i,
.bscode-nav .nav-link img {
  width: 1.35rem;
  height: 1.35rem;
  max-width: 1.35rem;
  max-height: 1.35rem;
  font-size: 1.35rem;
  line-height: 1;
}

.bscode-nav .nav-link > :not(.bscode-nav-label) {
  display: grid;
  place-items: center;
}

.bscode-nav .nav-link:hover,
.bscode-nav .nav-link:focus-visible {
  color: rgba(255, 255, 255, 0.98);
  background: rgba(255, 255, 255, 0.09);
}

.bscode-nav .nav-link.active {
  color: #fff;
  background: rgba(255, 255, 255, 0.13);
}

.bscode-position-left .bscode-nav .nav-link.active {
  border-left-color: #fff;
}

.bscode-position-right .bscode-nav .nav-link.active {
  border-right-color: #fff;
}

.bscode-letter-icon {
  display: grid;
  place-items: center;
  width: 1.55rem;
  height: 1.55rem;
  border: 1px solid currentColor;
  border-radius: 0.3rem;
  font-size: 0.85rem;
  font-weight: 600;
}

.bscode-tooltip-light {
  --bs-tooltip-bg: #ffffff;
  --bs-tooltip-color: #202326;
  --bs-tooltip-opacity: 1;
}

.bscode-tooltip-light .tooltip-inner {
  border: 1px solid rgba(32, 35, 38, 0.18);
  box-shadow: 0 2px 8px rgba(32, 35, 38, 0.18);
  font-size: 0.78rem;
  font-weight: 500;
}

.bscode-content {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  width: auto;
  height: 100%;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}

.bscode-header {
  flex: 0 0 auto;
  min-width: 0;
}

.bscode-tab-content {
  flex: 1 1 auto;
  width: 100%;
  height: auto;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}

.bscode-tab-content > .tab-pane {
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
}

.bscode-tab-content > .bscode-pane-fill.active {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.bscode-tab-content > .bscode-pane-scroll.active {
  overflow: auto;
}

@media (max-width: 600px) {
  .bscode-activity-bar,
  .bscode-brand,
  .bscode-nav .nav-link {
    width: 52px;
  }

  .bscode-activity-bar {
    flex-basis: 52px;
  }

  .bscode-brand {
    flex-basis: 52px;
    height: 52px;
  }

  .bscode-nav .nav-link {
    height: 50px;
  }
}

(function () {
  "use strict";

  function oppositePlacement(position) {
    return position === "right" ? "left" : "right";
  }

  function directLabel(link) {
    const text = Array.from(link.childNodes)
      .filter(function (node) { return node.nodeType === Node.TEXT_NODE; })
      .map(function (node) { return node.textContent.trim(); })
      .filter(Boolean)
      .join(" ");

    return text || link.textContent.trim() || link.dataset.value || "Panel";
  }

  function containsIcon(element) {
    return element.matches("svg, i, img, .bscode-letter-icon") ||
      Boolean(element.querySelector("svg, i, img, .bscode-letter-icon"));
  }

  function hideLabel(link) {
    Array.from(link.childNodes).forEach(function (node) {
      if (node.nodeType === Node.TEXT_NODE && node.textContent.trim()) {
        const label = document.createElement("span");
        label.className = "bscode-nav-label visually-hidden";
        label.textContent = node.textContent.trim();
        node.replaceWith(label);
      }
    });

    Array.from(link.children).forEach(function (child) {
      if (!containsIcon(child)) {
        child.classList.add("bscode-nav-label", "visually-hidden");
      }
    });
  }

  function hasIcon(link) {
    return Boolean(link.querySelector("svg, i, img, .bscode-letter-icon"));
  }

  function addLetterFallback(link, label) {
    if (hasIcon(link)) return;

    const letter = Array.from(label.trim())[0] || "?";
    const icon = document.createElement("span");
    icon.className = "bscode-letter-icon";
    icon.setAttribute("aria-hidden", "true");
    icon.textContent = letter.toUpperCase();
    link.prepend(icon);
  }

  function initLink(shell, link) {
    if (link.dataset.bscodeReady === "true") return;

    const label = directLabel(link);
    addLetterFallback(link, label);
    hideLabel(link);

    link.setAttribute("aria-label", label);
    link.removeAttribute("title");

    const requested = shell.dataset.bscodeTooltipPlacement || "auto";
    if (requested !== "none" && window.bootstrap && bootstrap.Tooltip) {
      const placement = requested === "auto"
        ? oppositePlacement(shell.dataset.bscodePosition || "left")
        : requested;

      bootstrap.Tooltip.getOrCreateInstance(link, {
        title: label,
        placement: placement,
        trigger: "hover focus",
        container: "body",
        customClass: "bscode-tooltip-light"
      });
    }

    link.dataset.bscodeReady = "true";
  }

  function initShell(shell) {
    shell.querySelectorAll(".bscode-nav .nav-link").forEach(function (link) {
      initLink(shell, link);
    });
  }

  function initAll() {
    document.querySelectorAll(".bscode-shell").forEach(initShell);
  }

  function resizeWidgets(shell) {
    window.dispatchEvent(new Event("resize"));

    if (window.Highcharts && Array.isArray(window.Highcharts.charts)) {
      window.Highcharts.charts.forEach(function (chart) {
        if (chart && chart.renderTo && shell.contains(chart.renderTo)) {
          chart.reflow();
        }
      });
    }

    if (window.Plotly && window.Plotly.Plots) {
      shell.querySelectorAll(".js-plotly-plot").forEach(function (plot) {
        window.Plotly.Plots.resize(plot);
      });
    }

    if (window.HTMLWidgets) {
      shell.querySelectorAll(".html-widget[id]").forEach(function (element) {
        try {
          const escaped = window.CSS && CSS.escape
            ? CSS.escape(element.id)
            : element.id;
          const widget = window.HTMLWidgets.find("#" + escaped);

          if (widget && typeof widget.getMap === "function") {
            const map = widget.getMap();
            if (map && typeof map.resize === "function") map.resize();
          }
        } catch (error) {
          // Other htmlwidgets respond to the window resize event above.
        }
      });
    }
  }

  document.addEventListener("DOMContentLoaded", initAll);
  document.addEventListener("shiny:connected", initAll);

  document.addEventListener("shown.bs.tab", function (event) {
    const shell = event.target.closest(".bscode-shell");
    if (!shell) return;

    window.requestAnimationFrame(function () {
      resizeWidgets(shell);
    });
  });

  new MutationObserver(initAll).observe(document.documentElement, {
    childList: true,
    subtree: true
  });
})();
